package com.ruoyi.library.service;
import com.ruoyi.common.exception.ServiceException;import com.ruoyi.library.domain.WlCourse;import com.ruoyi.library.domain.WlCourseVideo;import com.ruoyi.library.mapper.WlCourseMapper;import java.util.List;import org.springframework.stereotype.Service;
/** 课程和私有视频配置服务。 */
@Service public class CourseService
{private final WlCourseMapper mapper;public CourseService(WlCourseMapper m){mapper=m;}public List<WlCourse> list(WlCourse q){return mapper.selectList(q==null?new WlCourse():q);}public List<WlCourse> publicList(){return mapper.selectPublicList();}public WlCourse get(Long id){WlCourse c=mapper.selectById(id);if(c==null)throw new ServiceException("课程不存在");return c;}public int add(WlCourse c,String op){validate(c,false);c.setCreateBy(op);return mapper.insertCourse(c);}public int edit(WlCourse c,String op){validate(c,true);WlCourse old=get(c.getId());if(!old.getAccessType().equals(c.getAccessType())&&mapper.countUsage(c.getId())>0)throw new ServiceException("课程已有兑换码、授权或进度，不能修改访问类型");c.setUpdateBy(op);return mapper.updateCourse(c);}public List<WlCourseVideo> videos(Long id){get(id);return mapper.selectVideos(id);}public List<java.util.Map<String,Object>> publicVideos(Long id){WlCourse c=get(id);if(!"0".equals(c.getStatus()))throw new ServiceException("课程不存在或已停用");List<java.util.Map<String,Object>> result=new java.util.ArrayList<>();for(WlCourseVideo v:mapper.selectVideos(id)){if(!"0".equals(v.getStatus()))continue;java.util.Map<String,Object> item=new java.util.LinkedHashMap<>();item.put("id",v.getId());item.put("title",v.getTitle());item.put("durationSeconds",v.getDurationSeconds());item.put("sortOrder",v.getSortOrder());result.add(item);}return result;}public int saveVideo(WlCourseVideo v,String op){if(v==null||v.getCourseId()==null)throw new ServiceException("课程编号不能为空");get(v.getCourseId());if(v.getTitle()==null||v.getTitle().trim().isEmpty())throw new ServiceException("视频标题不能为空");if(v.getVideoObjectKey()==null||v.getVideoObjectKey().trim().isEmpty())throw new ServiceException("视频对象键不能为空");if(v.getDurationSeconds()==null||v.getDurationSeconds()<0)throw new ServiceException("视频时长不能小于0");if(v.getSortOrder()==null)throw new ServiceException("视频排序不能为空");if(!"0".equals(v.getStatus())&&!"1".equals(v.getStatus()))throw new ServiceException("视频状态不正确");if(v.getId()==null){v.setCreateBy(op);return mapper.insertVideo(v);}v.setUpdateBy(op);return mapper.updateVideo(v);}private void validate(WlCourse c,boolean id){if(c==null||id&&c.getId()==null)throw new ServiceException("课程编号不能为空");if(c.getTitle()==null||c.getTitle().trim().isEmpty())throw new ServiceException("课程标题不能为空");if(!"VIP".equals(c.getAccessType())&&!"CODE".equals(c.getAccessType()))throw new ServiceException("课程访问类型只能为会员或课程码");if(!"0".equals(c.getStatus())&&!"1".equals(c.getStatus()))throw new ServiceException("课程状态不正确");if(c.getSortOrder()==null)c.setSortOrder(0);if(c.getSummary()==null)c.setSummary("");}}
